'use strict';

function cloneBook(book) {
  if (
    book === null || typeof book !== 'object' || Array.isArray(book) ||
    typeof book.id !== 'string' || book.id.length === 0 ||
    typeof book.title !== 'string' || book.title.length === 0 ||
    !Number.isSafeInteger(book.pages) || book.pages <= 0
  ) throw new TypeError('Malformed book');
  return { id: book.id, title: book.title, pages: book.pages };
}

function cloneUniqueList(value) {
  if (!Array.isArray(value)) throw new TypeError('Books must be an array');
  const result = value.map(cloneBook);
  const ids = new Set(result.map(book => book.id));
  if (ids.size !== result.length) throw new RangeError('Duplicate book id');
  return result;
}

function updateShelf(books, command) {
  const current = cloneUniqueList(books);
  if (command === null || typeof command !== 'object' || Array.isArray(command) || typeof command.type !== 'string') {
    throw new TypeError('Malformed command');
  }

  if (command.type === 'REPLACE') return cloneUniqueList(command.payload);
  if (command.type === 'APPEND') {
    const added = cloneBook(command.payload);
    if (current.some(book => book.id === added.id)) throw new RangeError('Duplicate book id');
    return current.concat(command.payload);
  }
  if (command.type === 'REMOVE') {
    if (typeof command.payload !== 'string' || command.payload.length === 0) {
      throw new TypeError('Malformed id');
    }
    return current.filter(book => book.id !== command.payload).map(book => ({ ...book }));
  }
  if (command.type === 'REVISE') {
    const payload = command.payload;
    if (
      payload === null || typeof payload !== 'object' || Array.isArray(payload) ||
      typeof payload.id !== 'string' || payload.id.length === 0
    ) {
      throw new TypeError('Malformed revision');
    }
    const changes = payload.changes;
    if (changes === null || typeof changes !== 'object' || Array.isArray(changes)) {
      throw new TypeError('Malformed changes');
    }
    const keys = Object.keys(changes);
    if (keys.length === 0 || keys.some(key => key !== 'title' && key !== 'pages')) {
      throw new RangeError('Unsupported changes');
    }
    const index = current.findIndex(book => book.id === payload.id);
    if (index < 0) throw new RangeError('Unknown book id');
    const revised = cloneBook({ ...current[index], ...changes });
    return current.map((book, i) => i === index ? revised : { ...book });
  }
  throw new TypeError('Unknown command type');
}

module.exports = { updateShelf };

