'use strict';

const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['updateShelf']);
const { updateShelf } = api;

const original = [
  { id: 'a', title: 'Alpha', pages: 10 },
  { id: 'b', title: 'Beta', pages: 20 }
];
const snapshot = JSON.parse(JSON.stringify(original));

const appendedBook = { id: 'c', title: 'Gamma', pages: 30 };
const appended = updateShelf(original, { type: 'APPEND', payload: appendedBook });
assert.deepStrictEqual(appended, [...snapshot, appendedBook]);
assert.deepStrictEqual(original, snapshot);
assert.notStrictEqual(appended, original);
for (let i = 0; i < original.length; i++) assert.notStrictEqual(appended[i], original[i]);
assert.notStrictEqual(appended[2], appendedBook);
appended[0].title = 'changed';
appendedBook.title = 'changed payload';
assert.deepStrictEqual(original, snapshot);

const removed = updateShelf(original, { type: 'REMOVE', payload: 'a' });
assert.deepStrictEqual(removed, [{ id: 'b', title: 'Beta', pages: 20 }]);
assert.notStrictEqual(removed[0], original[1]);
const missing = updateShelf(original, { type: 'REMOVE', payload: 'missing' });
assert.deepStrictEqual(missing, original);
assert.notStrictEqual(missing, original);
assert.notStrictEqual(missing[0], original[0]);

const revised = updateShelf(original, {
  type: 'REVISE', payload: { id: 'b', changes: { title: 'Beta II', pages: 21 } }
});
assert.deepStrictEqual(revised, [
  { id: 'a', title: 'Alpha', pages: 10 },
  { id: 'b', title: 'Beta II', pages: 21 }
]);
assert.deepStrictEqual(original, snapshot);
assert.notStrictEqual(revised[0], original[0]);
assert.notStrictEqual(revised[1], original[1]);

const replacementPayload = [{ id: 'z', title: 'Last', pages: Number.MAX_SAFE_INTEGER }];
const replaced = updateShelf(original, { type: 'REPLACE', payload: replacementPayload });
assert.deepStrictEqual(replaced, replacementPayload);
assert.notStrictEqual(replaced, replacementPayload);
assert.notStrictEqual(replaced[0], replacementPayload[0]);
assert.deepStrictEqual(updateShelf(original, { type: 'REPLACE', payload: [] }), []);

assert.throws(() => updateShelf(original, { type: 'APPEND', payload: { id: 'a', title: 'Duplicate', pages: 1 } }), RangeError);
assert.throws(() => updateShelf(original, { type: 'REVISE', payload: { id: 'x', changes: { title: 'X' } } }), RangeError);
assert.throws(() => updateShelf(original, { type: 'REVISE', payload: { id: 'a', changes: {} } }), RangeError);
assert.throws(() => updateShelf(original, { type: 'REVISE', payload: { id: 'a', changes: { id: 'x' } } }), RangeError);

const malformedBooks = [
  null, {}, [{ id: '', title: 'T', pages: 1 }], [{ id: 'x', title: '', pages: 1 }],
  [{ id: 'x', title: 'T', pages: 0 }], [{ id: 'x', title: 'T', pages: 1.5 }],
  [{ id: 'x', title: 'T', pages: Number.MAX_SAFE_INTEGER + 1 }]
];
for (const books of malformedBooks) {
  assert.throws(() => updateShelf(books, { type: 'REMOVE', payload: 'x' }), TypeError);
}

const malformedPayloads = [
  { type: 'APPEND', payload: null },
  { type: 'APPEND', payload: { id: 'x', title: 'X', pages: Infinity } },
  { type: 'REMOVE', payload: '' },
  { type: 'REPLACE', payload: [{ id: 'x', title: 'X', pages: -1 }] },
  null,
  { type: 'UNKNOWN', payload: null }
];
for (const command of malformedPayloads) {
  assert.throws(() => updateShelf(original, command), TypeError);
  assert.deepStrictEqual(original, snapshot);
}

